function ensureDeckLayout(spec,side){const key=side==='top'?'topSequence':'bottomSequence',layout=deckLayout(spec,side).map(({_layoutWidth,...b})=>b);spec[key]=layout;return layout}

function deckLayout(spec,side){const key=side==='top'?'topSequence':'bottomSequence',rows=side==='top'?spec.topBoards:spec.bottomBoards,seq=makeDeckSequence(rows,spec[key]||[]),L=Math.max(1,Number(spec.length)||48),widths=seq.map(b=>boardDims(b)[1]),sum=widths.reduce((a,b)=>a+b,0),gap=seq.length>1?Math.max(0,(L-sum)/(seq.length-1)):0,compress=sum>L?L/Math.max(sum,1):1;let cursor=0;const out=seq.map((b,i)=>{const bw=Math.max(.125,(widths[i]||4)*compress);let pos=Number(b.position);if(!Number.isFinite(pos)){pos=cursor;cursor+=bw+(sum>L?0:gap)}pos=snapBoardPosition(spec,side,pos,bw);return {...b,position:pos,_layoutWidth:bw}});out.sort((a,b)=>a.position-b.position);return out}

