  let base='';const edge='var(--svg-edge,#6f4928)',fill='var(--svg-wood-side,#9b6734)';
  if(model.kind==='block'){for(let r=0;r<3;r++)for(let c=0;c<3;c++){const x=padX+c*usableW/2,y=padY+r*usableH/2;base+=`<rect x="${x-14}" y="${y-14}" width="28" height="28" rx="3" fill="${fill}" stroke="${edge}"/>`}}
  else {for(let i=0;i<model.count;i++){const y=padY+(model.count===1?usableH/2:i*usableH/Math.max(1,model.count-1));base+=`<rect x="${padX}" y="${y-8}" width="${usableW}" height="16" rx="3" fill="${fill}" stroke="${edge}"/>`;if(model.notched){for(const xx of [padX+usableW*.32,padX+usableW*.68])base+=`<rect x="${xx-13}" y="${y-10}" width="26" height="20" rx="2" class="svg-notch-cut" stroke="${edge}"/>`}}}
  const frame=`<rect x="${padX}" y="${padY}" width="${usableW}" height="${usableH}" rx="8" class="svg-frame"/>`,label=`${side==='top'?'Vista superior':'Vista inferior'} · ${model.label}`;
