    const snapshot=()=>{readCurrent();if(conditionUsesBuildSpec(c.condition)){c.topSequence=ensureDeckLayout(c,'top');c.bottomSequence=ensureDeckLayout(c,'bottom')}const r=palletTypeRules(c.type);return {...clone(c),materialOrigin:c.condition==='recycled'?'recycled':(c.condition==='combo_runner'?'combo-runner':(c.condition==='combo_board'?'combo-board':(c.condition==='combo'?'combo-pending':'new'))),name:`${c.length}×${c.width}`,maxHeight:r.maxHeight,canRotate:conditionIsFixed4840(c.condition)?true:r.canRotate}};
    document.getElementById('noAddProduct').onclick=()=>{const p=snapshot();draft.products.push(p);if(p.saveTemplate&&p.templateName){state.palletTemplates.push({...clone(p),id:'TPL-'+Date.now(),name:p.templateName,customer:draft.customer});save()}draft.current=productDraft();toast('Medida agregada a la orden.');phase2()};
    document.getElementById('noSave').onclick=()=>{const last=snapshot(),products=[...draft.products,last].map(p=>({...p,condition:p.condition||'new',materialOrigin:(p.condition||'new')==='recycled'?'recycled':((p.condition||'new')==='combo_runner'?'combo-runner':((p.condition||'new')==='combo_board'?'combo-board':((p.condition||'new')==='combo'?'combo-pending':'new')))}));if(last.saveTemplate&&last.templateName){state.palletTemplates.push({...clone(last),id:'TPL-'+Date.now(),name:last.templateName,customer:draft.customer})}const id=nextOrderId(),qty=products.reduce((n,p)=>n+p.qty,0),product=products.length===1?`${products[0].length}×${products[0].width}`:`${products.length} medidas · carga mixta`,loadItems=products.map(p=>{const r=palletTypeRules(p.type);return {name:`${p.length}×${p.width}`,length:p.length,width:p.width,quantity:p.qty,maxHeight:r.maxHeight,canRotate:r.canRotate,type:p.type,condition:p.condition||'new'}}),order={id,clientOrder:draft.clientOrder,clientReference:draft.clientReference,customer:draft.customer,product,qty,deliveryDate:draft.deliveryDate,deliveryTimeFrom:draft.deliveryTimeFrom,deliveryTimeTo:draft.deliveryTimeTo,due:draft.due||'Sin fecha',shipping:draft.shipping,condition:[...new Set(products.map(p=>p.condition||'new'))].length===1?(products[0].condition||'new'):'mixed',qcRequired:draft.qcRequired,htRequired:draft.htRequired,trailerReturn:draft.trailerReturn,trailerReturnNote:draft.trailerReturnNote,stage:'waiting_material',notes:draft.notes,products:clone(products),palletSpecs:clone(products),palletSpec:clone(products[0]),palletSku:products.length===1?(products[0].templateName||`${products[0].length}×${products[0].width}`):`MIX-${id}`,trailerWidth:96,trailerLength:628,loadItems};order.requiredPieces=finishedPieceRequirements({products});order.materialPlan=null;order.woodNeed=0;state.orders.push(order);save();closeDialog();toast(`Orden #${id} creada con ${products.length} medida(s).`);navigate('ordenes')};
